.checklist-check.is-checked{
  background:transparent;
  color:#065f46;
}
.checklist-check input{
  width:22px;
  height:22px;
  flex:0 0 auto;
}
.checklist-step{
  padding:3px 7px;
  border-radius:999px;
  background:#ffedd5;
  color:#ea580c;
  font-size:11px;
  letter-spacing:.04em;
  white-space:nowrap;
}
.checklist-summary{
  font-size:15px;
  line-height:1.15;
  font-weight:850;
  min-width:0;
}
.checklist-text,
.checklist-help,
.checklist-errors{
  display:none;
}
.checklist-info{
  justify-self:end;
}
.checklist-info summary{
  width:30px;
  height:30px;
  border-radius:50%;
  display:grid;
  place-items:center;
  border:1px solid rgba(37,99,235,.24);
  background:#eff6ff;
  color:#1d4ed8;
  font-size:15px;
  font-weight:900;
  cursor:pointer;
  list-style:none;
}
.checklist-info summary::-webkit-details-marker{
  display:none;
}
.checklist-info[open]{
  grid-column:1/-1;
  justify-self:stretch;
}
.checklist-info[open] summary{
  margin-left:auto;
}
.checklist-info-body{
  margin-top:7px;
  padding:9px 10px;
  border-radius:12px;
  background:#fff;
  border:1px solid rgba(148,163,184,.22);
  color:#334155;
  font-size:12px;
  line-height:1.35;
}
.checklist-info-body p{
  margin:0;
}
.checklist-info-body p+p{
  margin-top:5px;
}
.checklist-footer{
  padding:9px 12px calc(10px + env(safe-area-inset-bottom));
  gap:10px;
}
.checklist-footer-status{
  font-size:12px;
  line-height:1.2;
}
.validate-checklist-btn{
  min-width:0;
  min-height:44px;
  padding:10px 14px;
  border-radius:14px;
  font-size:14px;
}
body.mobile-mode .checklist-overlay{
  padding:6px;
  align-items:center;
}
body.mobile-mode .checklist-card{
  width:min(410px,calc(100vw - 10px));
  height:auto;
  max-height:min(92dvh,760px);
  border-radius:20px;
}
body.mobile-mode .checklist-header{
  padding:10px 12px;
}
body.mobile-mode .checklist-title{
  font-size:18px;
}
body.mobile-mode .checklist-close{
  width:34px;
  height:34px;
  font-size:20px;
}
body.mobile-mode .checklist-intro{
  padding:7px 12px;
  font-size:11px;
}
body.mobile-mode .checklist-grid{
  gap:6px;
  padding:8px 9px;
  grid-template-columns:none;
  overflow:auto;
}
body.mobile-mode .checklist-item{
  padding:7px 8px;
  gap:6px;
  border-right:1px solid rgba(148,163,184,.2);
}
body.mobile-mode .checklist-check{
  grid-template-columns:auto auto minmax(0,1fr);
  gap:7px;
  min-height:0;
  padding:0;
}
body.mobile-mode .checklist-check input{
  width:20px;
  height:20px;
}
body.mobile-mode .checklist-step{
  font-size:10px;
  padding:3px 6px;
}
body.mobile-mode .checklist-summary{
  font-size:13px;
  line-height:1.12;
}
body.mobile-mode .checklist-info summary{
  width:28px;
  height:28px;
  font-size:14px;
}
body.mobile-mode .checklist-info-body{
  font-size:11px;
  line-height:1.3;
  padding:8px 9px;
}
body.mobile-mode .checklist-footer{
  padding:8px 10px calc(9px + env(safe-area-inset-bottom));
  gap:7px;
}
body.mobile-mode .checklist-footer-status{
  font-size:11px;
}
body.mobile-mode .validate-checklist-btn{
  min-height:42px;
  padding:9px 12px;
  font-size:14px;
}
